import React, { useEffect } from 'react';
import CartItem from './CartItem';
import OrderSummary from './OrderSummary';
import './Cart.css'; // Your CSS file is imported here
import { useNavigate } from 'react-router-dom';
import { useCart } from './hooks';

const CartPage = () => {
    const {
        cart,
        loading,
        error,
        fetchCart,
        updateCartItem,
        removeFromCart,
        clearCart,
    } = useCart();
    const navigate = useNavigate();

    useEffect(() => {
        const token = localStorage.getItem('token');
        if (!token) {
            navigate('/login');
        } else {
            fetchCart();
        }
    }, [navigate, fetchCart]);

    const handleUpdateQuantity = (productId, newQuantity) => {
        if (newQuantity <= 0) {
            removeFromCart(productId);
        } else {
            updateCartItem(productId, newQuantity);
        }
    };

    // --- CHANGES START HERE ---

    // REPLACED inline style with a className
    if (loading) return <div className="cart-page-message">Loading your cart...</div>;
    
    // REPLACED inline style with two classNames
    if (error) return <div className="cart-page-message error">Error: {error}</div>;

    // REPLACED inline style with a specific className for the empty state
    if (!cart || !cart.items || cart.items.length === 0) {
        return (
            <div className="cart-page-empty">
                <h2>Your Shopping Cart is Empty</h2>
                <p>Start shopping to add items to your cart!</p>
                <button 
                    onClick={() => navigate('/')}
                    // REPLACED large style block with reusable button classes
                    className="checkout-btn" 
                >
                    Continue Shopping
                </button>
            </div>
        );
    }

    return (
        <div className="cart-page">
            <main className="cart-items-container">
                {/* REPLACED inline style div with a new className for the header */}
                <div className="cart-header">
                    <h2>Shopping Cart</h2>
                    <button 
                        onClick={clearCart}
                        // REPLACED style block with a specific className
                        className="clear-cart-btn"
                    >
                        Clear Cart
                    </button>
                </div>
                {cart.items.map(item => (
                    <CartItem 
                        key={item.productId}
                        item={item}
                        onUpdateQuantity={handleUpdateQuantity}
                        onRemoveItem={removeFromCart}
                    />
                ))}
            </main>
            <OrderSummary cart={cart} />
        </div>
    );
};

export default CartPage;
